async function chargeCard(
  payment: PaymentDetails,
  amount: number
): Promise<ChargeResult> {
  const query = 'INSERT INTO payments (card_last_four, amount, status) VALUES ($1, $2, $3) RETURNING id';
  const lastFour = payment.cardNumber.slice(-4);

