function isSubscriptionValid(validUntil: Date): boolean {
  return validUntil >= new Date();
}

function parseSubscriptionRow(row: unknown): Subscription {
  // Type guard or validation library would be ideal here
  const r = row as Record<string, unknown>;
  return {
    userId: String(r.user_id),
    tier: r.tier as 'free' | 'premium' | 'enterprise',
    validUntil: new Date(r.valid_until as string),
    features: JSON.parse(r.features as string) as string[]
  };
}

export async function hasFeatureAccess(userId: string, feature: string): Promise<boolean> {
  const subscription = await getUserSubscription(userId);
  if (!subscription) return false;
  if (!isSubscriptionValid(subscription.validUntil)) return false;
  return subscription.features.includes(feature);
}

export async function getUserSubscription(userId: string): Promise<Subscription | null> {
  const query = 'SELECT * FROM subscriptions WHERE user_id = $1';
  const rows = await db.query(query, [userId]);
  if (rows.length === 0) return null;

  return parseSubscriptionRow(rows[0]);
}
